#include <bits/stdc++.h>using namespace std;#define int long longconst int N = 35 * 2e5 + 5;int tree[N][2],cnt[N],path[N];int T,q,x,id = 1;char opt; void add(string s){	int p = 0,len = s.size();	for(int i=0;i<len;i++){		int num = s[i] - '0';		if(tree[p][num] == 0){			tree[p][num] = id;			id++;		}		p = tree[p][num];		path[p]++;		if(i == len - 1)cnt[p]++;	}} void cut(string s){	int p = 0,len = s.size();	for(int i=0;i<len;i++){		int num = s[i] - '0';		if(tree[p][num] == 0){			return ;		}		p = tree[p][num];		path[p]--;		if(i == len - 1)cnt[p]--;	}} string bi(int dec){	string res = "";	while(dec){		res += (dec & 1) + '0';		dec >>= 1;	}	reverse(res.begin(),res.end());	while(res.size() < 32){		res = "0" + res;	}	return res;} int calc(string s){	int res = 0,len = s.size(),wei = 0;	for(int i=len-1;i>=0;i--){		res += (s[i] - '0') << wei;		wei++;	}	return res;} void ask(){	string s = bi(x),ss = "",sss = "";	int p = 0,len = s.size();	for(int i=0;i<len;i++){		int num = s[i] - '0',rev = num ^ 1;		if(tree[p][rev] && path[tree[p][rev]] > 0){			p = tree[p][rev];			ss += rev + '0';		}else if(tree[p][num] && path[tree[p][num]] > 0){			p = tree[p][num];			ss += num + '0';		}	} 	for(int i=0;i<len;i++){		if(s[i] == ss[i])sss += '0';		else sss += '1';	}	cout << calc(sss) << '\n';} void O_o(){	// init();	cin >> q;	add(bi(0));	while(q--){		cin >> opt >> x;		if(opt == '+')add(bi(x));		if(opt == '-')cut(bi(x));		if(opt == '?')ask();	}} signed main(){	ios::sync_with_stdio(false);cin.tie(nullptr);	T = 1;while(T--)O_o();	return 0;}